create or replace function public.business_campaign_analytics(p_business_id uuid, p_start timestamptz default now()-interval '30 days', p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path to 'public','pg_temp' as $$
begin
 if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if;
 return (with cs as (select c.id,c.status from public.enterprise_partner_campaigns c join public.enterprise_partner_networks n on n.id=c.network_id where n.owner_business_id=p_business_id), os as (select o.campaign_id,sum(o.visits) visits,sum(o.check_ins) check_ins,sum(o.reviews) reviews,sum(o.attributed_users) attributed_users,sum(o.points_awarded) points_awarded from public.enterprise_partner_campaign_outcomes o where o.metric_date between p_start::date and p_end::date group by o.campaign_id) select jsonb_build_object('business_id',p_business_id,'campaigns',count(*),'active_campaigns',count(*) filter(where cs.status='active'),'outcome_visits',coalesce(sum(os.visits),0),'outcome_check_ins',coalesce(sum(os.check_ins),0),'outcome_reviews',coalesce(sum(os.reviews),0),'attributed_users',coalesce(sum(os.attributed_users),0),'points_awarded',coalesce(sum(os.points_awarded),0)) from cs left join os on os.campaign_id=cs.id);
end; $$;

create or replace function public.get_business_engagement_funnel(p_business_id uuid, p_start timestamptz default now()-interval '30 days', p_end timestamptz default now()) returns table(activity_type text, source text, events bigint, unique_users bigint) language plpgsql security definer set search_path to 'public','pg_temp' as $$
begin
 if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if;
 return query select activity_type,source,count(*)::bigint,count(distinct user_id)::bigint from public.business_engagement_attributions where business_id=p_business_id and created_at between p_start and p_end group by activity_type,source order by count(*) desc;
end; $$;

create or replace function public.get_location_details(p_location_id uuid) returns jsonb language sql security definer set search_path to 'public','pg_temp' as $$
 select jsonb_build_object('location',jsonb_build_object('id',l.id,'business_id',l.business_id,'name',l.name,'address',l.address,'city',l.city,'state',l.state,'postal_code',l.postal_code,'country',l.country,'latitude',l.latitude,'longitude',l.longitude,'place_type',l.place_type,'phone',l.phone,'website',l.website,'description',l.description,'is_active',l.is_active,'accessible',l.accessible,'changing_table',l.changing_table,'cleanliness',l.cleanliness,'cleanliness_pct',l.cleanliness_pct,'rating',l.rating,'review_count',l.review_count,'smart_bathroom',l.smart_bathroom,'promo_offer',l.promo_offer,'bathroom_verification_status',l.bathroom_verification_status,'bathroom_verified_at',l.bathroom_verified_at,'bathroom_verification_count',l.bathroom_verification_count,'bathroom_positive_count',l.bathroom_positive_count,'bathroom_negative_count',l.bathroom_negative_count,'bathroom_verification_source',l.bathroom_verification_source,'source',l.source,'source_dataset',l.source_dataset,'source_external_id',l.source_external_id,'source_metadata',coalesce(l.source_metadata->'tags','{}'::jsonb),'verification_observation_count',l.verification_observation_count,'verification_positive_count',l.verification_positive_count,'verification_negative_count',l.verification_negative_count,'verification_confidence',l.verification_confidence),'business',case when b.id is null then null else jsonb_build_object('id',b.id,'name',b.name,'description',b.description,'website',b.website,'phone',b.phone,'logo_url',b.logo_url,'verification_status',b.verification_status) end,'amenities',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'category',a.category) order by a.category,a.name) from public.location_amenities la join public.amenities a on a.id=la.amenity_id where la.location_id=l.id),'[]'::jsonb),'promotions',coalesce((select jsonb_agg(to_jsonb(p) order by p.starts_at nulls last,p.title) from public.promotions p where p.location_id=l.id and coalesce(p.active,true) and (p.ends_at is null or p.ends_at>=now())),'[]'::jsonb),'events',coalesce((select jsonb_agg(to_jsonb(e) order by e.event_date,e.event_time) from public.business_events e where e.location_id=l.id and e.event_date>=current_date),'[]'::jsonb),'osm_tags',coalesce(l.source_metadata->'tags','{}'::jsonb),'verification',jsonb_build_object('status',coalesce(l.bathroom_verification_status,'unverified'),'verified',coalesce(l.bathroom_verification_status,'unverified') in ('has_bathroom','verified'),'verified_at',l.bathroom_verified_at,'source',l.bathroom_verification_source)) from public.locations l left join public.businesses b on b.id=l.business_id where l.id=p_location_id;
$$;
